typedef float rational_t;
#define NULL 0
#define assert(x) ((void)0)

struct vector3d { float x, y, z; };
struct vector4d { float x, y, z, w; };

class po
{
  vector4d m[4];
public:
  void set_position(const vector3d& p) { m[3].x = p.x; m[3].y = p.y; m[3].z = p.z; }
};

extern po po_identity_matrix;

class stringx
{
  char data[8];
public:
  const char* c_str() const;
};

class visual_rep;
class vm_thread;

class entity
{
  char padding[80];
  po* my_abs_po;
public:
  const vector3d& get_abs_position() const { return *(const vector3d*)((const char*)my_abs_po + 48); }
  vm_thread* spawn_entity_script_function(const stringx&) const;
  void change_visrep(const stringx&);
  void set_visible(bool);
  void set_collisions_active(bool, bool = true);
  void set_walkable(bool);
  void set_repulsion(bool);
  void set_active(bool);
  void set_actionable(bool);
};

class world_dynamics_system
{
public:
  entity* add_time_limited_effect(const char*, const po&, rational_t);
};

extern world_dynamics_system* g_world_ptr;
void unload_visual_rep(visual_rep*);

class destroyable_info
{
protected:
  short flags;
  rational_t destroy_lifetime;
  stringx destroy_fx;
  stringx destroy_script;
  stringx destroyed_visrep;
  stringx preload_script;
  visual_rep* destroyed_mesh;
  int hit_points;
  virtual void copy_instance_data(destroyable_info*);
  entity* owner;

public:
  enum eDestroyInfoFlags
  {
    _DESTROY_FX = 0x0002,
    _DESTROY_SCRIPT = 0x0004,
    _DESTROYED_VISREP = 0x0010,
    _REMAIN_VISIBLE = 0x0040,
    _REMAIN_ACTIVE = 0x0080,
    _NO_COLLISION = 0x0400,
    _REMAIN_COLLISION = 0x0800
  };

  bool is_flagged(eDestroyInfoFlags f) const { return (flags & f) != 0; }
  bool has_destroy_fx() const { return is_flagged(_DESTROY_FX); }
  bool has_destroy_script() const { return is_flagged(_DESTROY_SCRIPT); }
  bool has_destroyed_visrep() const { return is_flagged(_DESTROYED_VISREP) && destroyed_mesh != NULL; }
  bool remain_visible() const { return is_flagged(_REMAIN_VISIBLE); }
  bool no_collision() const { return is_flagged(_NO_COLLISION); }
  bool remain_collision() const { return is_flagged(_REMAIN_COLLISION); }
  bool remain_active() const { return is_flagged(_REMAIN_ACTIVE); }
  const stringx& get_destroy_script() const { return destroy_script; }
  void apply_destruction_fx();
};

void destroyable_info::apply_destruction_fx()
{
  assert(owner != NULL);

//  if(dread_net_cue != dread_net::UNDEFINED_AV_CUE)
//    g_world_ptr->get_dread_net()->add_cue((dread_net::eAVCueType)dread_net_cue, owner);

  if ( has_destroy_fx() )
  {
    po the_po = po_identity_matrix;
    the_po.set_position(owner->get_abs_position());
//    entity *fx =  // unused, remove me?
    g_world_ptr->add_time_limited_effect( destroy_fx.c_str(), the_po, destroy_lifetime );
  }

  if ( has_destroy_script() )
  {
    owner->spawn_entity_script_function( get_destroy_script() );
  }

  if ( has_destroyed_visrep() )
  {
    owner->change_visrep(destroyed_visrep);
    unload_visual_rep(destroyed_mesh);
    destroyed_mesh = NULL;
  }
  else if ( !remain_visible() )
  {
    owner->set_visible( false );

    if( !remain_collision() )
    {
      owner->set_collisions_active( false );
      owner->set_walkable( false );
      owner->set_repulsion( false );
    }
  }

  if( no_collision() )
  {
    owner->set_collisions_active( false );
    owner->set_walkable( false );
    owner->set_repulsion( false );
  }

  if ( !remain_active() )
  {
    owner->set_active( false );
    owner->set_actionable( false );
  }
}
